"""Build a standalone visual mock from the existing console markup. No runtime JS is included."""
from html.parser import HTMLParser
from html import escape
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).with_name('expert-concept.html')
VOID = {'input','br','hr','img','meta','link','source','area','wbr','embed','param','col'}

class Extract(HTMLParser):
    def __init__(self, device):
        super().__init__(convert_charrefs=True); self.device=device; self.stack=[]; self.current=None; self.depth=0; self.parts=[]; self.views={}
    def handle_starttag(self, tag, attrs):
        a=dict(attrs); classes=a.get('class','').split(); key=None
        if self.current is None:
            if self.device=='GLD' and tag=='section' and 'view' in classes: key=a.get('id')
            elif self.device!='GLD' and tag=='section' and 'panel' in classes: key=a.get('data-panel')
            elif a.get('id') in {'opsPanel','setupPanel','runningSettingsPanel','datasetSettingsPanel','nullingSettingsPanel','settingsPanel','firmwareUploadDialog','fullScaleSweepModal','nullingDetailsModal'}: key=a.get('id')
            if key: self.current=key; self.depth=0; self.parts=[]
        if self.current is None: return
        if tag not in VOID: self.depth+=1
        if tag in {'script','link'}: return
        clean=[]
        for k,v in attrs:
            if k in {'hidden','disabled','aria-hidden','style','autofocus','formaction'} or k.startswith('on'): continue
            if k in {'href','src','action'}: continue
            if k=='class': v=' '.join(x for x in (v or '').split() if x not in {'hidden','active','drawer','drawer-panel','panel','view','modal','modal-box','upload-dialog','upload-dialog-box','drawer-panel--wide'})
            if k=='id': k='data-original-id'
            if k in {'data-panel','data-tab'}: continue
            clean.append(' '+k+(('="'+escape(v,quote=True)+'"') if v is not None else ''))
        if tag=='a': tag='span'
        self.parts.append('<'+tag+''.join(clean)+'>')
        if tag in VOID and self.depth==0: self.finish()
    def handle_startendtag(self,tag,attrs):
        self.handle_starttag(tag,attrs)
        if tag not in VOID: self.handle_endtag(tag)
    def handle_endtag(self,tag):
        if self.current is None or tag in VOID: return
        if tag=='a': tag='span'
        self.parts.append('</'+tag+'>'); self.depth-=1
        if self.depth==0: self.finish()
    def handle_data(self,data):
        if self.current is not None: self.parts.append(escape(data))
    def finish(self):
        self.views[self.current]=''.join(self.parts); self.current=None; self.parts=[]

data={}
for d,path in [('GLD','gld-operator'),('CH','ch-operator'),('Gateway','gw-operator')]:
    p=Extract(d); p.feed((ROOT/path/'index.html').read_text(encoding='utf-8')); data[d]=p.views

template=r'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expert Console — mockup</title><style>
:root{font-family:Inter,"Segoe UI",sans-serif;color:#202f47;background:#f4f7fb;font-size:14px}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer}.layout{display:grid;grid-template-columns:240px minmax(0,1fr);min-height:100vh}.sidebar{background:#fff;border-right:1px solid #e5ebf4;padding:25px 16px;display:flex;flex-direction:column}.brand{display:flex;gap:12px;align-items:center;padding:2px 7px 25px}.brand i{font-style:normal;display:grid;place-items:center;width:40px;height:40px;border-radius:12px;color:white;background:#3353d4;font-weight:800}.brand strong,.brand small{display:block}.brand small{color:#95a2b5;font-size:10px;letter-spacing:.1em;margin-top:3px}.side-label{color:#9aa7b9;font-weight:800;font-size:10px;letter-spacing:.1em;margin:20px 10px 9px}.devices,.nav{display:grid;gap:4px}.devices button,.nav button{border:0;background:transparent;text-align:left;padding:11px 12px;border-radius:9px;color:#66768d;font-weight:650}.devices button.active,.nav button.active{background:#edf1ff;color:#3452cc}.devices button span,.nav button span{display:inline-block;width:28px}.sidefoot{margin-top:auto;background:#f5f7fc;border-radius:12px;padding:14px;font-size:12px;color:#8491a4;line-height:1.5}.sidefoot strong{display:block;color:#3e506d}.main{min-width:0}.top{height:68px;background:white;border-bottom:1px solid #e6ecf4;display:flex;align-items:center;justify-content:space-between;padding:0 36px}.top small{color:#91a0b4}.top strong{color:#324461}.badge{background:#fff4dd;color:#9a6b13;padding:7px 11px;border-radius:99px;font-weight:700;font-size:11px}.content{padding:32px 36px 60px;max-width:1500px;margin:auto}.head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:20px}.eyebrow{font-size:10px;color:#6780dd;letter-spacing:.13em;font-weight:800}.head h1{font-size:29px;letter-spacing:-.04em;margin:7px 0}.head p{color:#8b99ac;margin:0}.preview{background:#eaf0ff;border:1px solid #d9e3ff;color:#536a9a;padding:12px 16px;border-radius:10px;margin:0 0 20px;font-size:12px}.context{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 20px}.context button,.mock button{border:1px solid #dce4ef;background:#fff;border-radius:8px;padding:9px 12px;color:#41536e;font-weight:650}.context button:hover,.mock button:hover{border-color:#a7b7ef;background:#f5f7ff}.mock{background:#fff;border:1px solid #e4eaf3;border-radius:16px;padding:24px;overflow:auto;box-shadow:0 7px 25px #2e436007}.mock h2{font-size:19px;letter-spacing:-.025em;color:#233655}.mock h3{font-size:14px;color:#344966}.mock h4{color:#4c607d}.mock p,.mock small,.mock .hint{color:#8896aa;line-height:1.5}.mock .grid,.mock .sensor-grid,.mock .cards,.mock .setting-grid,.mock .wf-layout{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.mock .card,.mock .module,.mock .wf-step,.mock .wf-sample-panel,.mock .wf-panel,.mock .chart-analysis,.mock .nulling-card{border:1px solid #e7ecf4;border-radius:12px;padding:16px;margin:0 0 12px;background:#fbfcfe}.mock .module .module{background:#fff}.mock label{display:inline-grid;gap:6px;color:#657790;font-size:12px;font-weight:650;margin:7px 10px 7px 0}.mock input:not([type=checkbox]):not([type=radio]),.mock select,.mock textarea{border:1px solid #dbe3ef;background:#fff;border-radius:8px;padding:9px;color:#314461;min-width:130px;max-width:100%}.mock input[type=checkbox],.mock input[type=radio]{accent-color:#4561d4}.mock button{margin:4px}.mock table{border-collapse:collapse;min-width:650px;width:100%;font-size:12px}.mock th,.mock td{padding:10px;border-bottom:1px solid #edf1f6;text-align:left}.mock pre{white-space:pre-wrap;background:#f3f6fb;padding:14px;border-radius:8px;color:#7789a5}.mock details{border:1px solid #e7ecf4;border-radius:12px;padding:14px;margin:10px 0}.mock summary{cursor:pointer;font-weight:700}.mock canvas{display:block;width:100%;height:150px;border-radius:10px;background:repeating-linear-gradient(0deg,#fff,#fff 29px,#eef2f8 30px)}.mock svg{max-width:38px;max-height:38px}.mock [class*=backdrop],.mock [data-original-id=globalBanner],.mock [data-original-id=appModal]{display:none}.mock .chart-container{min-height:160px}.mock .tag,.mock .badge{background:#edf2ff;color:#5b72c9;padding:5px 8px;border-radius:6px}.mock .section-head,.mock .module-head,.mock .actions,.mock .btn-row{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.mock .sr-only,.mock .wf-visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.toast{position:fixed;bottom:20px;right:20px;background:#283d6d;color:white;padding:13px 18px;border-radius:9px;box-shadow:0 8px 25px #26355333}.hidden{display:none}.mock [data-original-id=qcGroupNavTrack]:empty:after{content:'Sensor  ·  Nulling  ·  Radio  ·  Sistem';color:#6f82b3}.mock [data-original-id=wfRows]:empty:after{content:'Data simulasi belum direkam'}.mock [data-original-id=sensorCards]:empty:after{content:'MQ8   ·   MQ135   ·   MQ3   ·   MQ5   ·   MQ4   ·   MQ7   ·   MQ6   ·   MQ2';color:#7386a3}@media(max-width:800px){.layout{grid-template-columns:minmax(0,1fr)}.sidebar,.main,.content{min-width:0}.sidebar{padding:15px}.sidefoot,.side-label{display:none}.brand{padding-bottom:10px}.devices,.nav{display:flex;overflow:auto}.devices button,.nav button{white-space:nowrap}.top{padding:0 20px}.content{padding:25px 18px}.head{align-items:start}}
</style></head><body><div class="layout"><aside class="sidebar"><div class="brand"><i>E</i><div><strong>Expert Console</strong><small>PERTAMINA GLD</small></div></div><p class="side-label">PERANGKAT</p><div id="devices" class="devices"></div><p class="side-label">AREA KERJA</p><nav id="nav" class="nav" aria-label="Area kerja expert"></nav><div class="sidefoot"><strong>Mockup interaktif</strong>Seluruh koneksi, nilai, dan tindakan adalah simulasi.</div></aside><main class="main"><header class="top"><div><small>Expert Console / </small><strong id="breadcrumb"></strong></div><span class="badge">MODE SIMULASI</span></header><div class="content"><div class="head"><div><div class="eyebrow" id="kicker"></div><h1 id="title"></h1><p id="description">Tampilan konsep untuk ditinjau dan dijelajahi.</p></div></div><div class="preview"><strong>Pratinjau desain.</strong> Semua area dapat dibuka tanpa koneksi. Data contoh; tombol tidak mengirim perintah atau mengubah perangkat.</div><div id="context" class="context"></div><div id="mock" class="mock"></div></div></main></div><div id="toast" class="toast hidden" role="status"></div><script>
const DATA=__DATA__;const menus={GLD:[['running','Running'],['dataset','Dataset'],['nulling','Nulling'],['qc','Quality Control'],['log','Serial Log'],['expert','Expert Terminal'],['opsPanel','Ops Panel'],['setupPanel','Port Setup'],['runningSettingsPanel','Running Settings'],['datasetSettingsPanel','Dataset Settings'],['nullingSettingsPanel','Nulling Settings'],['firmwareUploadDialog','Firmware Upload'],['fullScaleSweepModal','MCP Sweep'],['nullingDetailsModal','Nulling Details']],CH:[['overview','Overview'],['nodes','Nodes (GLD)'],['mesh','Mesh / Parent'],['log','Serial Log'],['expert','Expert Terminal'],['setupPanel','Port Setup'],['settingsPanel','CH Settings'],['firmwareUploadDialog','Firmware Upload']],Gateway:[['overview','Overview'],['uplinks','Uplinks'],['topology','Topology'],['commands','Commands'],['log','Boot Log'],['firmware','Firmware'],['setupPanel','Gateway Setup'],['firmwareUploadDialog','Firmware Upload']]};let device='GLD',page='running';const $=s=>document.querySelector(s);function render(){let options=menus[device],label=(options.find(x=>x[0]===page)||options[0])[1];$('#devices').innerHTML=['GLD','CH','Gateway'].map((d,i)=>`<button data-device="${d}" class="${d===device?'active':''}"><span>${['◉','◈','⬡'][i]}</span>${d}</button>`).join('');$('#nav').innerHTML=options.map(([k,n],i)=>`<button data-nav="${k}" class="${k===page?'active':''}"><span>${['▦','◷','◎','◇','≡','⌘'][i%6]}</span>${n}</button>`).join('');$('#breadcrumb').textContent=device+' / '+label;$('#kicker').textContent=device.toUpperCase()+' / EXPERT CONSOLE';$('#title').textContent=label;$('#context').innerHTML=options.filter(([k])=>/Settings|Panel|firmwareUploadDialog|setupPanel/.test(k)).map(([k,n])=>`<button data-nav="${k}">${n} ↗</button>`).join('');$('#mock').innerHTML=DATA[device][page]||'<p>Bagian ini belum tersedia dalam sumber.</p>';$('#mock').querySelectorAll('button').forEach(b=>b.type='button');$('#mock').querySelectorAll('form').forEach(f=>f.addEventListener('submit',e=>e.preventDefault()));window.scrollTo(0,0)}document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.device){device=b.dataset.device;page=menus[device][0][0];render()}else if(b.dataset.nav){page=b.dataset.nav;render()}else if(b.closest('#mock')){let t=$('#toast');t.textContent='Simulasi: '+(b.textContent.trim().replace(/\s+/g,' ').slice(0,55)||'tindakan')+' · tidak ada perintah dikirim';t.classList.remove('hidden');clearTimeout(window.timer);window.timer=setTimeout(()=>t.classList.add('hidden'),3500)}});render();</script></body></html>'''
OUT.write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</',r'<\/')),encoding='utf-8')
print('Built',OUT, {k:list(v) for k,v in data.items()})

